/* ============================================
   打印格式样式 (Print Format Styles)
   适用于库存调账标准打印格式模板
   注意：通用样式已合并到 standard.css，此处仅保留模板特定样式
   ============================================ */

/* 基本信息表格样式 */
.print-format-wrapper .info-table {
    margin-bottom: 16px;
}

.print-format-wrapper .info-table .info-cell {
    padding: 4px;
    vertical-align: top;
}

.print-format-wrapper .info-label {
    display: inline-block;
    min-width: 60px;
    margin-right: 5px;
    color: #171717;
}

.print-format-wrapper .info-value {
    color: #171717;
}

/* 物料明细表格样式 */
.print-format-wrapper .items-table {
    margin-bottom: 16px;
}

/* 物料信息单元格 */
.print-format-wrapper .item-info-cell {
    text-align: left;
}

.print-format-wrapper .item-code {
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 2px;
    color: #171717;
}

.print-format-wrapper .item-name {
    font-size: 12px;
    color: #171717;
    margin-bottom: 2px;
}

.print-format-wrapper .secondary-text {
    font-size: 11px;
    color: #666;
    line-height: 1.3;
}

/* 仓库单元格 */
.print-format-wrapper .warehouse-cell {
    text-align: left;
    color: #171717;
}

/* 数量单元格 */
.print-format-wrapper .quantity-cell {
    text-align: right;
}

.print-format-wrapper .quantity-value {
    font-size: 13px;
    font-weight: 600;
    color: #171717;
}

/* 复选框样式 */
.print-format-wrapper .check-box-outline {
    width: 14px;
    height: 14px;
    border: 1px solid #333;
    display: inline-block;
    background-color: #fff;
    margin: 0 auto;
}

/* 签名表格样式 */
