{% if found_project_name %}
{% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
{% else %}
{% set project_display = found_project_id %}
{% endif %}
{% endif %}

{% for page in layout %}
<div class="page-break print-format-wrapper order-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>
	{%- if doc.meta.is_submittable and doc.docstatus==2-%}
		<div class="text-center" document-status="cancelled">
			<h4 style="margin-top: 20px;">{{ _("CANCELLED") }}</h4>
		</div>
	{%- endif -%}
	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}
		<div class="text-center" document-status="draft">
			<h4 style="margin-top: 20px !important;">{{ _("DRAFT") }}</h4>
		</div>
	{%- endif -%}

	<div class="print-format-body">
        <!-- 基本信息表格 -->
        <table class="table table-bordered info-table mb-3">
            <tbody>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">单号:</span>
                        <span class="info-value text-bold">{{ doc.name }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">日期:</span>
                        <span class="info-value">{{ frappe.utils.format_date(doc.creation) }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">用途:</span>
                        <span class="info-value">{{ _(doc.purpose) or "&nbsp;" }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">项目:</span>
                        <span class="info-value text-bold">{{ project_display or "&nbsp;" }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">关联 ({{ source_label }}):</span>
                        <span class="info-value">{{ source_name or "&nbsp;" }}</span>
                    </td>
                </tr>
            </tbody>
        </table>

        <!-- 物料明细表格 -->
        <table class="table table-bordered items-table mb-3">
            <thead class="table-header">
                <tr>
                    <th class="text-center" style="width: 6%;">序号</th>
                    <th class="text-left" style="width: 36%;">物料信息</th>
                    <th class="text-left" style="width: 15%;">源仓库</th>
                    <th class="text-left" style="width: 20%;">批次/序列号</th>
                    <th class="text-right" style="width: 15%;">数量</th>
                    <th class="text-center" style="width: 8%;">✔</th>
                </tr>
            </thead>
            <tbody>
                {%- for item in doc.locations -%}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="item-info-cell">
                        <div class="item-code text-bold">{{ item.item_code }}</div>
                        <div class="item-name">{{ item.item_name }}</div>
                    </td>
                    <td class="warehouse-cell">{{ item.warehouse or "--" }}</td>
                    <td class="batch-serial-cell">
                        {%- if item.batch_no -%}
                        <div class="secondary-text">[批] {{ item.batch_no }}</div>
                        {% endif %}
                        {%- if item.serial_no -%}
                        <div class="secondary-text">[序] {{ item.serial_no }}</div>
                        {% endif %}
                        {%- if not item.batch_no and not item.serial_no -%}
                        &nbsp;
                        {% endif %}
                    </td>
                    <td class="text-right quantity-cell">
                        <span class="quantity-value text-bold">{{ item.picked_qty }}</span>
                        <span class="quantity-uom">{{ item.uom }}</span>
                    </td>
                    <td class="text-center check-cell">
                        <div class="check-box-outline"></div>
                    </td>
                </tr>
                {%- endfor -%}
            </tbody>
        </table>

        <!-- 备注区域 -->
        <div class="remarks-box mb-3">
            <div class="remarks-label font-weight-bold mb-2">备注:</div>
            <div class="remarks-content">{{ doc.remarks or "&nbsp;" }}</div>
        </div>

        <!-- 签名区域 -->
        <table class="table table-borderless signature-table">
            <tbody>
                <tr>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">制单人:</div>
                        {%- if doc.owner -%}
                        <div class="signature-name text-bold mt-2">{{ doc.owner }}</div>
                        {%- else -%}
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        {% endif %}
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">拣货人:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">复核人:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">接收人:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                </tr>
            </tbody>
        </table>
	</div>
</div>
{% endfor %}

css:
/* ============================================
   打印格式样式 (Print Format Styles)
   适用于标准打印格式模板
   注意：通用样式已合并到 standard.css，此处仅保留模板特定样式
   ============================================ */

/* 基本信息表格样式 - 仅保留模板特定的 padding 设置 */
.print-format-wrapper .info-table {
    margin-bottom: 16px;
}

.print-format-wrapper .info-table .info-cell {
    padding: 4px;
    vertical-align: top;
}

.print-format-wrapper .info-label {
    display: inline-block;
    min-width: 60px;
    margin-right: 5px;
    color: #171717;
}

.print-format-wrapper .info-value {
    color: #171717;
}

/* 物料明细表格样式 - 仅保留模板特定的 margin 设置 */
.print-format-wrapper .items-table {
    margin-bottom: 16px;
}

/* 物料信息单元格 */
.print-format-wrapper .item-info-cell {
    text-align: left;
}

.print-format-wrapper .item-code {
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 2px;
    color: #171717;
}

.print-format-wrapper .item-name {
    font-size: 12px;
    color: #171717;
    margin-bottom: 2px;
}

.print-format-wrapper .item-description {
    font-size: 11px;
    color: #666;
    margin-top: 2px;
    line-height: 1.3;
}

/* 仓库单元格 */
.print-format-wrapper .warehouse-cell {
    text-align: left;
    color: #171717;
}

/* 批次/序列号单元格 */
.print-format-wrapper .batch-serial-cell {
    text-align: left;
}

/* 数量单元格 */
.print-format-wrapper .quantity-cell {
    text-align: right;
}

.print-format-wrapper .quantity-value {
    font-size: 13px;
    font-weight: 600;
    color: #171717;
    margin-right: 3px;
}

.print-format-wrapper .quantity-uom {
    font-size: 12px;
    color: #666;
}

/* 备注区域样式 */
.print-format-wrapper .remarks-box {
    border: 1px solid #333;
    padding: 10px;
    min-height: 80px;
    font-size: 12px;
    margin-bottom: 16px;
}

.print-format-wrapper .remarks-label {
    margin-bottom: 6px;
    color: #171717;
}

.print-format-wrapper .remarks-content {
    color: #171717;
    line-height: 1.6;
    margin: 0;
}

/* 金额汇总表格样式 - 仅保留模板特定的 padding 设置 */
.print-format-wrapper .totals-table td {
    padding: 4px;
    vertical-align: middle;
}

/* 签名表格样式 - 仅保留模板特定的 padding 设置 */
.print-format-wrapper .signature-table td {
    padding: 4px;
    vertical-align: top;
}

html:
{%- macro add_header(doc, letter_head, no_letterhead) -%}
{% if letter_head and not no_letterhead %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}
{%- endmacro -%}

{% set source_label = "无" %}
{% set source_name = "" %}
{% set project_display = "" %}
{% set req_type_map = {
    "Purchase": "采购",
    "Material Transfer": "材料转移/调拨",
    "Material Issue": "领料/出库",
    "Manufacture": "生产制造",
    "Customer Provided": "客户提供"
} %}

{# --- 1. 尝试从子表第一行获取关联来源与项目 --- #}
{% set found_project_id = "" %}
{% if doc.items and doc.items|length > 0 %}
{% set first_line = doc.items[0] %}

{# 获取项目ID #}
{% if first_line.project %}
{% set found_project_id = first_line.project %}
{% endif %}

{# 获取来源单据 #}
{% if first_line.work_order %}
{% set source_label = "生产工单" %}
{% set source_name = first_line.work_order %}
{% elif first_line.sales_order %}
{% set source_label = "销售订单" %}
{% set source_name = first_line.sales_order %}
{% elif first_line.job_card %}
{% set source_label = "作业卡" %}
{% set source_name = first_line.job_card %}
{% endif %}
{% endif %}

{# --- 2. 拼接项目名称: ID (名称) --- #}
{% if found_project_id %}
{% set found_project_name = frappe.db.get_value("Project", found_project_id, "project_name") %}
{% if found_project_name %}
{% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
{% else %}
{% set project_display = found_project_id %}
{% endif %}
{% endif %}

<div class="page-break print-format-wrapper">
    <div id="header-html" class="hidden-pdf">
        {{ add_header(doc, letter_head, no_letterhead) }}
    </div>

    <div class="print-format-body">
        {% if doc.title %}
        <div class="text-center mb-3 mt-3">
            <div style="font-size: 16px; font-weight: bold;">{{ doc.title }}</div>
        </div>
        {% endif %}

        <!-- 基本信息表格 -->
        <table class="table table-bordered info-table mb-3">
            <tbody>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">单号:</span>
                        <span class="info-value text-bold">{{ doc.name }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">日期:</span>
                        <span class="info-value">{{ frappe.utils.format_date(doc.transaction_date) }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">类型:</span>
                        <span class="info-value">{{ req_type_map.get(doc.material_request_type, doc.material_request_type) }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">项目:</span>
                        <span class="info-value text-bold">{{ project_display or "&nbsp;" }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">关联 ({{ source_label }}):</span>
                        <span class="info-value">{{ source_name or "&nbsp;" }}</span>
                    </td>
                </tr>
            </tbody>
        </table>

        <!-- 物料明细表格 -->
        <table class="table table-bordered items-table mb-3">
            <thead class="table-header">
                <tr>
                    <th class="text-center" style="width: 6%;">序号</th>
                    <th class="text-left" style="width: 36%;">物料信息</th>
                    <th class="text-left" style="width: 20%;">目标仓库</th>
                    <th class="text-left" style="width: 15%;">需求日期</th>
                    <th class="text-right" style="width: 15%;">数量</th>
                    <th class="text-center" style="width: 8%;">✔</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.items %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="item-info-cell">
                        <div class="item-code text-bold">{{ item.item_code }}</div>
                        <div class="item-name">{{ item.item_name }}</div>
                        {% if item.description and item.description != item.item_name %}
                        <div class="item-description secondary-text">{{ item.description | striptags }}</div>
                        {% endif %}
                    </td>
                    <td class="warehouse-cell">{{ item.warehouse or "--" }}</td>
                    <td>{{ frappe.utils.format_date(item.schedule_date) }}</td>
                    <td class="text-right quantity-cell">
                        <span class="quantity-value text-bold">{{ item.qty }}</span>
                        <span class="quantity-uom">{{ item.uom }}</span>
                    </td>
                    <td class="text-center check-cell">
                        <div class="check-box-outline"></div>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>

        <!-- 备注区域 -->
        <div class="remarks-box mb-3">
            <div class="remarks-label font-weight-bold mb-2">备注:</div>
            <div class="remarks-content">{{ doc.remarks or "&nbsp;" }}</div>
        </div>

        <!-- 签名区域 -->
        <table class="table table-borderless signature-table">
            <tbody>
                <tr>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">申请人 (制单):</div>
                        {% if doc.owner %}
                        <div class="signature-name text-bold mt-2">{{ doc.owner }}</div>
                        {% else %}
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        {% endif %}
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">部门主管:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">计划/采购:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">批准:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</div>

