				</tr>
				{%- endfor -%}
			</tbody>
		</table>

		<!-- 金额汇总：有金额时与标准版一致；无金额时留空供供应商填写 -->
		<div class="mb-3" style="text-align: right;">
			<table class="table table-bordered totals-table" style="margin-left: auto; width: auto; min-width: 400px;">
