						<td class="text-right text-bold {% if not frappe.utils.flt(doc.grand_total) %}cell-supplier-fill{% endif %}" style="min-width: 120px;">
							{%- if frappe.utils.flt(doc.grand_total) != 0 -%}
							{{ doc.in_words or "&nbsp;" }}
							{%- else -%}
							&nbsp;
							{%- endif -%}
						</td>
