html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{%- if letter_head and not no_letterhead -%}
		<div class="letter-head">{{ letter_head }}</div>
	{%- endif -%}
	{%- if print_heading_template -%}
		{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
	{%- endif -%}
{%- endmacro -%}

{%- macro fmt_qty(qty) -%}
{%- if qty % 1 == 0 -%}
{{- "{:,.0f}".format(qty) -}}
{%- else -%}
{{- "{:,.2f}".format(qty) -}}
{%- endif -%}
{%- endmacro -%}

{% set project_display = "" %}
{% set buyer_company_name = frappe.db.get_value("Company", doc.company, "company_name") if doc.company else "" %}

{# --- 1. 获取项目信息 (从主表或第一行子表) --- #}
{% set found_project_id = "" %}
{% if doc.project %}
{% set found_project_id = doc.project %}
{% elif doc.items and doc.items|length > 0 and doc.items[0].project %}
{% set found_project_id = doc.items[0].project %}
{% endif %}

{# --- 2. 拼接项目名称: ID (名称) --- #}
{% if found_project_id %}
{% set found_project_name = frappe.db.get_value("Project", found_project_id, "project_name") %}
{% if found_project_name %}
{% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
{% else %}
{% set project_display = found_project_id %}
{% endif %}
{% endif %}

{# --- 3. 获取供应商联系人信息 (如果有) --- #}
{% set contact_display = "" %}
{% if doc.contact_person %}
{% set contact_display = doc.contact_display or doc.contact_person %}
{% set contact_mobile = frappe.db.get_value("Contact", doc.contact_person, "mobile_no") %}
{% if contact_mobile %}
{% set contact_display = contact_display ~ " (" ~ contact_mobile ~ ")" %}
{% endif %}
{% endif %}

{# --- 4. 收货地址：优先 Address.custom_address_display，否则 shipping_address_display --- #}
{% set shipping_display = "" %}
{% if doc.shipping_address and frappe.db.exists("Address", doc.shipping_address) %}
{% set shipping_display = frappe.db.get_value("Address", doc.shipping_address, "custom_address_display") or "" %}
{% endif %}
{% if not shipping_display %}
{% set shipping_display = doc.get("shipping_address_display") or "" %}
{% endif %}

{# --- 5. 收货联系人 / 电话 --- #}
{% set ship_contact_name = "" %}
{% if doc.custom_shipping_contact_person %}
{% set ship_contact_name = frappe.db.get_value("Contact", doc.custom_shipping_contact_person, "full_name") or doc.custom_shipping_contact_person %}
{% endif %}
{% set ship_contact_phone = doc.custom_shipping_contact_phone or "" %}

{# --- 6. 项目关联客户（最终收货/使用单位参考） --- #}
{% set project_customer_display = "" %}
{% if found_project_id %}
{% set proj_cust = frappe.db.get_value("Project", found_project_id, "customer") %}
{% if proj_cust %}
{% set project_customer_display = frappe.db.get_value("Customer", proj_cust, "customer_name") or proj_cust %}
{% endif %}
{% endif %}

{% set show_shipping_block = shipping_display or ship_contact_name or ship_contact_phone %}

{% for page in layout %}
<div class="page-break print-format-wrapper order-wrapper proxy-delivery-print">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>


	<div class="print-format-body">
        <div class="proxy-delivery-heading text-center mb-2">
            <h2 class="mb-0">直发单</h2>
        </div>
        <div class="direct-ship-principal text-center mb-3">
            <span class="principal-label font-weight-bold">委托方：</span>
            <span class="principal-value">{{ buyer_company_name or doc.company or "" }}</span>
        </div>

        <!-- 基本信息表格 -->
        <table class="table table-bordered info-table mb-3">
            <tbody>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">供应商:</span>
                        <span class="info-value text-bold">{{ doc.supplier_name }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">单号:</span>
                        <span class="info-value text-bold">{{ doc.name }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">发货方:</span>
                        <span class="info-value">{{ contact_display or "&nbsp;" }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">日期:</span>
                        <span class="info-value">{{ frappe.utils.format_date(doc.transaction_date) }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">关联项目:</span>
                        <span class="info-value text-bold">{{ project_display or "&nbsp;" }}</span>
                    </td>
                </tr>
                {% if project_customer_display %}
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">项目客户:</span>
                        <span class="info-value text-bold">{{ project_customer_display }}</span>
                    </td>
                </tr>
                {% endif %}
                {% if show_shipping_block %}
                {% if shipping_display and (shipping_display | trim) %}
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label">收货地址:</span>
                        <span class="info-value">{{ shipping_display | trim }}</span>
                    </td>
                </tr>
                {% endif %}
                {% if ship_contact_name or ship_contact_phone %}
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">收货方:</span>
                        <span class="info-value">{{ ship_contact_name or "—" }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">电话:</span>
                        <span class="info-value">{{ ship_contact_phone or "—" }}</span>
                    </td>
                </tr>
                {% endif %}
                {% endif %}
            </tbody>
        </table>

        <!-- 物料明细表格（无交货日期、无价格、无行描述） -->
        <table class="table table-bordered items-table mb-3">
            <thead class="table-header">
                <tr>
                    <th class="text-center" style="width: 6%;">序号</th>
                    <th class="text-left" style="width: 44%;">物料信息</th>
                    <th class="text-left" style="width: 26%;">仓库</th>
                    <th class="text-right" style="width: 24%;">数量</th>
                </tr>
            </thead>
            <tbody>
                {%- for item in doc.items -%}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="item-info-cell">
                        <div class="item-code text-bold">{{ item.item_code }}</div>
                        <div class="item-name">{{ item.item_name }}</div>
                        {% if item.supplier_part_no %}
                        <div class="secondary-text" style="margin-top: 2px;">[供]: {{ item.supplier_part_no }}</div>
                        {% endif %}
                    </td>
                    <td class="text-left warehouse-cell">
                        {%- set wh = item.get("warehouse") -%}
                        {%- if wh -%}
                        {{- frappe.db.get_value("Warehouse", wh, "warehouse_name") or wh -}}
                        {%- else -%}
                        —
                        {%- endif -%}
                    </td>
                    <td class="text-right quantity-cell">
                        <span class="quantity-value text-bold">{{ fmt_qty(item.qty) }}</span>
                        <span class="quantity-uom">{{ item.uom }}</span>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>

        <div class="proxy-delivery-disclaimer">
            直发交接单 · 非合同与结算依据 · 价格、付款及条款以系统采购订单为准
        </div>
	</div>
</div>
{% endfor %}

css:
/* ============================================
   打印格式样式 (Print Format Styles)
   适用于标准打印格式模板
   ============================================ */

/* 主容器样式 */
.print-format-wrapper {
    font-family: "HarmonyOS Sans SC", "HarmonyOSHans-Regular", "PingFangSC-Regular", "Microsoft YaHei", "Arial", "Helvetica", sans-serif;
    font-size: 13px;
    line-height: 1.6;
    color: #171717;
    margin: 0;
    padding: 0;
    position: relative;
}

/* 标题样式 */
.print-format-wrapper .header-title {
    margin-top: 0;
    margin-bottom: 20px;
}

.print-format-wrapper .header-title h2 {
    font-size: 20px;
    font-weight: 700;
    color: #171717;
    letter-spacing: 1px;
    margin: 0;
}

/* 基本信息表格样式 */
.print-format-wrapper .info-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 16px;
    font-size: 12px;
    border: 1px solid #333;
}

.print-format-wrapper .info-table .info-cell {
    padding: 4px;
    border: 1px solid #333;
    vertical-align: top;
}

.print-format-wrapper .info-label {
    display: inline-block;
    min-width: 60px;
    margin-right: 5px;
    color: #171717;
}

.print-format-wrapper .info-value {
    color: #171717;
}

/* 物料明细表格样式 */
.print-format-wrapper .items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 16px;
    font-size: 12px;
    border: 1px solid #333;
}

.print-format-wrapper .items-table thead {
    background-color: #f5f5f5;
}

.print-format-wrapper .items-table th {
    font-weight: 600;
    color: #171717;
    padding: 4px;
    text-align: center;
    border: 1px solid #333;
    background-color: #f5f5f5;
    vertical-align: middle;
}

.print-format-wrapper .items-table td {
    padding: 4px;
    border: 1px solid #333;
    vertical-align: middle;
    line-height: 1.5;
}

.print-format-wrapper .items-table tbody tr {
    background-color: #fff;
}

/* 隔行变色 */
.print-format-wrapper .items-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

/* 物料信息单元格 */
.print-format-wrapper .item-info-cell {
    text-align: left;
}

.print-format-wrapper .item-code {
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 2px;
    color: #171717;
}

.print-format-wrapper .item-name {
    font-size: 12px;
    color: #171717;
    margin-bottom: 2px;
}

.print-format-wrapper .item-description {
    font-size: 11px;
    color: #666;
    margin-top: 2px;
    line-height: 1.3;
}

/* 仓库单元格 */
.print-format-wrapper .warehouse-cell {
    text-align: left;
    color: #171717;
}

/* 批次/序列号单元格 */
.print-format-wrapper .batch-serial-cell {
    text-align: left;
}

/* 数量单元格 */
.print-format-wrapper .quantity-cell {
    text-align: right;
}

.print-format-wrapper .quantity-value {
    font-size: 13px;
    font-weight: 600;
    color: #171717;
    margin-right: 3px;
}

.print-format-wrapper .quantity-uom {
    font-size: 12px;
    color: #666;
}

/* 复选框样式 */
.print-format-wrapper .check-box-outline {
    width: 14px;
    height: 14px;
    border: 1px solid #333;
    display: inline-block;
    background-color: #fff;
    margin: 0 auto;
}

/* 备注区域样式 */
.print-format-wrapper .remarks-box {
    border: 1px solid #333;
    padding: 10px;
    min-height: 80px;
    font-size: 12px;
    margin-bottom: 16px;
}

.print-format-wrapper .remarks-label {
    margin-bottom: 6px;
    color: #171717;
}

.print-format-wrapper .remarks-content {
    color: #171717;
    line-height: 1.6;
    margin: 0;
}

/* 签名表格样式 */
.print-format-wrapper .signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
    font-size: 12px;
}

.print-format-wrapper .signature-table td {
    border: none;
    padding: 4px;
    vertical-align: top;
}

.print-format-wrapper .signature-cell {
    text-align: left;
    min-height: 80px;
    height: 80px;
}

.print-format-wrapper .signature-label {
    font-weight: 600;
    color: #171717;
    margin-bottom: 4px;
}

.print-format-wrapper .signature-name {
    font-weight: 600;
    color: #171717;
}

.print-format-wrapper .signature-line {
    border-top: 1px solid #333;
    width: 90%;
    margin-top: 8px;
    height: 1px;
}

/* 次要文本样式 */
.print-format-wrapper .secondary-text {
    font-size: 11px;
    color: #666;
    line-height: 1.3;
}

/* 文本对齐工具类 */
.print-format-wrapper .text-center {
    text-align: center;
}

.print-format-wrapper .text-left {
    text-align: left;
}

.print-format-wrapper .text-right {
    text-align: right;
}

.print-format-wrapper .text-bold {
    font-weight: 600;
}

/* 间距工具类 */
.print-format-wrapper .mb-2 {
    margin-bottom: 8px;
}

.print-format-wrapper .mb-3 {
    margin-bottom: 16px;
}

.print-format-wrapper .mt-2 {
    margin-top: 8px;
}

/* 打印优化 */
@media print {
    .print-format-wrapper {
        page-break-inside: avoid;
    }
    
    .print-format-wrapper .items-table {
        page-break-inside: auto;
    }
    
    .print-format-wrapper .items-table tbody tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }
    
    .print-format-wrapper .items-table thead {
        display: table-header-group;
    }
    
    .print-format-wrapper .signature-table {
        page-break-inside: avoid;
    }
}

/* 确保表格在打印时正确显示 */
.print-format-wrapper .items-table,
.print-format-wrapper .info-table {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{%- if letter_head and not no_letterhead -%}
		<div class="letter-head">{{ letter_head }}</div>
	{%- endif -%}
	{%- if print_heading_template -%}
		{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
	{%- endif -%}
{%- endmacro -%}

{% set source_label = "无" %}
{% set source_name = "" %}
{% set project_display = "" %}
{% set owner_full_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner or "" %}

{# --- 1. 主表优先：关联来源（与 stock-entry-standard 一致） --- #}
{% if doc.work_order %}
{% set source_label = "生产工单" %}
{% set source_name = doc.work_order %}
{% elif doc.bom_no %}
{% set source_label = "BOM" %}
{% set source_name = doc.bom_no %}
{% elif doc.purchase_order %}
{% set source_label = "采购订单" %}
{% set source_name = doc.purchase_order %}
{% elif doc.material_request %}
{% set source_label = "物料需求" %}
{% set source_name = doc.material_request %}
{% endif %}

{# --- 2. 若主表无关联，再从子表第一行补全（与物料需求模板一致） --- #}
{% if not source_name and doc.items and doc.items|length > 0 %}
{% set first_line = doc.items[0] %}
{% if first_line.work_order %}
{% set source_label = "生产工单" %}
{% set source_name = first_line.work_order %}
{% elif first_line.sales_order %}
{% set source_label = "销售订单" %}
{% set source_name = first_line.sales_order %}
{% elif first_line.job_card %}
{% set source_label = "作业卡" %}
{% set source_name = first_line.job_card %}
{% endif %}
{% endif %}

{# --- 3. 项目：主表 > 子表首行 > 工单反查 --- #}
{% set found_project_id = "" %}
{% if doc.project %}
{% set found_project_id = doc.project %}
{% elif doc.items and doc.items|length > 0 and doc.items[0].project %}
{% set found_project_id = doc.items[0].project %}
{% elif doc.work_order %}
{% set found_project_id = frappe.db.get_value("Work Order", doc.work_order, "project") %}
{% elif doc.items and doc.items|length > 0 and doc.items[0].work_order %}
{% set found_project_id = frappe.db.get_value("Work Order", doc.items[0].work_order, "project") %}
{% endif %}

{# --- 4. 拼接项目名称 --- #}
{% if found_project_id %}
{% set found_project_name = frappe.db.get_value("Project", found_project_id, "project_name") %}
{% if found_project_name %}
{% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
{% else %}
{% set project_display = found_project_id %}
{% endif %}
{% endif %}

{% for page in layout %}
<div class="page-break print-format-wrapper order-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>

	<div class="print-format-body">
		{%- if doc.title -%}
        <div class="text-center mb-3 mt-3">
            <div style="font-size: 16px; font-weight: bold;">{{ doc.title }}</div>
        </div>
        {% endif %}

        <!-- 基本信息表格 -->
        <table class="table table-bordered info-table mb-3">
            <tbody>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">移库单号:</span>
                        <span class="info-value text-bold">{{ doc.name }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">过账日期:</span>
                        <span class="info-value">{{ frappe.utils.format_date(doc.posting_date) }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">移库类型:</span>
                        <span class="info-value">{{ _(doc.stock_entry_type) }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">项目:</span>
                        <span class="info-value text-bold">{{ project_display or "&nbsp;" }}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">公司:</span>
                        <span class="info-value">{{ doc.company or "&nbsp;" }}</span>
                    </td>
                    <td class="info-cell" style="width: 50%;">
                        <span class="info-label font-weight-bold">过账时间:</span>
                        <span class="info-value">{% if doc.posting_time %}{{ frappe.utils.format_time(doc.posting_time) }}{% else %}&nbsp;{% endif %}</span>
                    </td>
                </tr>
                <tr>
                    <td class="info-cell" colspan="2">
                        <span class="info-label font-weight-bold">关联 ({{ source_label }}):</span>
                        <span class="info-value">{{ source_name or "&nbsp;" }}</span>
                    </td>
                </tr>
            </tbody>
        </table>

        <!-- 物料明细表格（Stock Entry：源/目标仓、批次序列号） -->
        <table class="table table-bordered items-table mb-3">
            <thead class="table-header">
                <tr>
                    <th class="text-center" style="width: 5%;">序号</th>
                    <th class="text-left" style="width: 26%;">物料信息</th>
                    <th class="text-left" style="width: 12%;">源仓库</th>
                    <th class="text-left" style="width: 12%;">目标仓库</th>
                    <th class="text-left" style="width: 16%;">批次/序列号</th>
                    <th class="text-right" style="width: 11%;">数量</th>
                    <th class="text-center" style="width: 6%;">✔</th>
                </tr>
            </thead>
            <tbody>
                {%- for item in doc.items -%}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="item-info-cell">
                        <div class="item-code text-bold">{{ item.item_code }}</div>
                        <div class="item-name">{{ item.item_name }}</div>
                        {%- if item.description and item.description != item.item_name -%}
                        <div class="item-description secondary-text">{{ item.description | striptags }}</div>
                        {% endif %}
                    </td>
                    <td class="warehouse-cell">{{ item.s_warehouse or item.warehouse or "--" }}</td>
                    <td class="warehouse-cell">{{ item.t_warehouse or item.warehouse or "--" }}</td>
                    <td class="batch-serial-cell">
                        {%- if item.batch_no -%}
                        <div class="secondary-text">[批] {{ item.batch_no }}</div>
                        {%- endif -%}
                        {%- if item.serial_no -%}
                        <div class="secondary-text">[序] {{ item.serial_no }}</div>
                        {%- endif -%}
                        {%- if not item.batch_no and not item.serial_no -%}
                        &nbsp;
                        {%- endif -%}
                    </td>
                    <td class="text-right quantity-cell">
                        <span class="quantity-value text-bold">{{ item.qty }}</span>
                        <span class="quantity-uom">{{ item.uom }}</span>
                    </td>
                    <td class="text-center check-cell">
                        <div class="check-box-outline"></div>
                    </td>
                </tr>
                {%- endfor -%}
            </tbody>
        </table>

        <!-- 备注区域 -->
        <div class="remarks-box mb-3">
            <div class="remarks-label font-weight-bold mb-2">备注:</div>
            <div class="remarks-content">{{ doc.remarks or "&nbsp;" }}</div>
        </div>

        <!-- 签名区域（与移库专用模板一致：发/收/审） -->
        <table class="table table-borderless signature-table">
            <tbody>
                <tr>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">制单人:</div>
                        {%- if owner_full_name -%}
                        <div class="signature-name text-bold mt-2">{{ owner_full_name }}</div>
                        {%- else -%}
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        {%- endif -%}
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">发货人 (源):</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">收货人 (目标):</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                    <td class="signature-cell" style="width: 25%; vertical-align: top;">
                        <div class="signature-label">审核/监管:</div>
                        <div class="signature-name text-bold mt-2" style="min-height: 1.2em;">&nbsp;</div>
                        <div class="signature-line mt-2"></div>
                    </td>
                </tr>
            </tbody>
        </table>
	</div>
</div>
{% endfor %}

css:
/* ============================================
   销售订单合同打印格式样式
   ============================================ */

.contract-header {
    text-align: center;
    margin-bottom: 20px;
}

.contract-number {
    text-align: right;
    font-size: 12px;
    margin-bottom: 10px;
}

.header-title {
    text-align: center;
    font-size: 24px;
    font-weight: bold;
    margin: 15px 0;
    letter-spacing: 3px;
}

.contract-parties {
    margin-bottom: 15px;
    font-size: 13px;
}

.party-line {
    margin-bottom: 8px;
    display: flex;
    align-items: baseline;
}

.party-label {
    width: 80px;
    font-weight: bold;
    flex-shrink: 0;
}

.party-value {
    border-bottom: 1px solid #000;
    flex: 1;
    min-width: 200px;
    padding-bottom: 2px;
    display: inline-block;
}

.party-value:empty::after {
    content: '\00a0';
}

.contract-date-location {
    display: flex;
    justify-content: space-between;
    margin-bottom: 20px;
    font-size: 13px;
}

.date-location-item {
    display: flex;
    align-items: baseline;
}

.date-location-label {
    margin-right: 5px;
    font-weight: bold;
}

.date-location-value {
    border-bottom: 1px solid #000;
    min-width: 150px;
    padding-bottom: 2px;
    display: inline-block;
}

.date-location-value:empty::after {
    content: '\00a0';
}

.regulatory-info {
    text-align: center;
    font-size: 11px;
    color: #666;
    margin-bottom: 20px;
    padding-top: 10px;
    border-top: 1px solid #ddd;
}

.notice-section {
    margin-bottom: 20px;
    padding: 10px;
    background-color: #f9f9f9;
    border: 1px solid #ddd;
    font-size: 11px;
    line-height: 1.8;
}

.notice-title {
    font-weight: bold;
    font-size: 13px;
    margin-bottom: 8px;
}

.notice-content {
    margin-bottom: 5px;
}

.section-title {
    font-weight: bold;
    font-size: 14px;
    margin-top: 20px;
    margin-bottom: 10px;
    page-break-after: avoid;
}

.section-subtitle {
    font-weight: bold;
    font-size: 13px;
    margin-top: 15px;
    margin-bottom: 8px;
}

.item-table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    margin-bottom: 20px;
    font-size: 11px;
    table-layout: fixed;
}

.item-table th,
.item-table td {
    border: 1px solid #000;
    padding: 6px 4px;
    vertical-align: middle;
    text-align: center;
    word-wrap: break-word;
}

.item-table th {
    background-color: #f0f0f0;
    font-weight: bold;
    font-size: 12px;
}

.item-table td.text-left {
    text-align: left;
}

.item-table td.text-right {
    text-align: right;
}

.clause-content {
    font-size: 12px;
    line-height: 1.8;
    margin-bottom: 12px;
}

.checkbox-item {
    margin-bottom: 6px;
    display: flex;
    align-items: baseline;
}

.checkbox {
    width: 14px;
    height: 14px;
    border: 1px solid #000;
    display: inline-block;
    margin-right: 3px;
    margin-left: 2px;
    margin-top: 0 !important;
    flex-shrink: 0;
    vertical-align: middle;
    position: relative;
    top: 2px;
}

/* 覆盖 Bootstrap 的 checkbox 样式干扰 */
.checkbox+.checkbox {
    margin-top: 0 !important;
}

.checkbox-label {
    margin-right: 8px;
}

.fill-field {
    border-bottom: 1px solid #000;
    min-width: 100px;
    display: inline-block;
    padding-bottom: 2px;
    margin: 0 3px;
}

.fill-field:empty::after {
    content: '\00a0';
}

.signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 30px;
    font-size: 11px;
    table-layout: fixed;
}

.signature-table td {
    border: none;
    padding: 8px 6px;
    vertical-align: top;
    width: 50%;
}

.signature-table th {
    border: none;
    padding: 8px 6px;
    background-color: transparent;
    font-weight: bold;
    text-align: center;
    font-size: 12px;
}

.signature-info {
    margin-bottom: 6px;
    font-size: 11px;
    line-height: 1.8;
    display: flex;
    align-items: baseline;
}

.signature-label {
    font-weight: bold;
    margin-right: 8px;
    text-align: right;
    min-width: 120px;
    flex-shrink: 0;
}

.signature-value {
    border-bottom: 1px solid #000;
    min-width: 150px;
    flex: 1;
    display: inline-block;
    padding-bottom: 2px;
    vertical-align: baseline;
}

.signature-value:empty::after {
    content: '\00a0';
}

/* PDF和打印优化 */
@media print {
    * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .print-format {
        padding: 0 !important;
        margin: 0 !important;
        font-size: 11px !important;
    }

    .item-table {
        border-collapse: collapse !important;
        width: 100% !important;
        table-layout: fixed !important;
    }

    .item-table th,
    .item-table td {
        border: 1px solid #000 !important;
        padding: 5px 3px !important;
    }

    .item-table th {
        background-color: #f0f0f0 !important;
    }

    .signature-table th,
    .signature-table td {
        border: none !important;
        padding: 6px 4px !important;
    }

    .signature-table th {
        background-color: transparent !important;
    }

    .section-title,
    .section-subtitle {
        page-break-after: avoid !important;
    }

    .notice-section {
        page-break-inside: avoid !important;
    }
}

@page {
    margin: 8mm 10mm;
    size: A4;
}

.print-format {
    box-sizing: border-box;
    width: 100%;
}

/* 确保PDF导出时边距正确 */
body {
    margin: 0 !important;
    padding: 0 !important;
}

/* 覆盖Frappe默认的print-format padding */
body .print-format {
    padding: 0 !important;
    margin: 0 !important;
}

/* ============================================
   合同内容区域样式 (contract-content)
   ============================================ */

/* 主容器样式 */
.contract-content {
    font-family: "HarmonyOS Sans SC", "HarmonyOSHans-Regular", "PingFangSC-Regular", "Microsoft YaHei", "Arial", "Helvetica", sans-serif;
    font-size: 13px;
    line-height: 1.8;
    color: #171717;
    text-align: justify;
    margin: 0;
    padding: 0;
}

/* 前言说明文字颜色统一为黑色 */
.regulatory-info,
.regulatory-info.text-muted {
    color: #171717 !important;
}

/* 章节标题样式（第一条、第二条等） */
.contract-content .section-title {
    font-size: 15px;
    font-weight: 700;
    color: #171717;
    margin-top: 24px;
    margin-bottom: 16px;
    line-height: 1.6;
    letter-spacing: 0.5px;
}

/* 第一个章节标题不需要上边距 */
.contract-content .section-title:first-child {
    margin-top: 0;
}

/* 子章节标题样式（1.1、1.2等） */
.contract-content .section-subtitle {
    font-size: 14px;
    font-weight: 600;
    color: #2c3e50;
    margin-top: 18px;
    margin-bottom: 12px;
    line-height: 1.6;
    letter-spacing: 0.3px;
}

/* 条款内容容器 */
.contract-content .clause-content {
    margin-bottom: 16px;
    padding-left: 1.5em;
}

/* 条款项样式 */
.contract-content .clause-item {
    font-size: 13px;
    line-height: 2;
    color: #171717;
    margin-bottom: 10px;
    text-align: justify;
    text-indent: 0;
    padding-left: 0;
}

/* 缩进条款项（如 4.1.2.1、4.1.2.2 等） */
.contract-content .clause-item.indent {
    padding-left: 2em;
    text-indent: -2em;
    margin-left: 0;
}

/* 下划线样式优化 */
.contract-content u {
    text-decoration: underline;
    text-underline-offset: 0.15em;
    text-decoration-thickness: 1px;
    text-decoration-color: #171717;
    padding: 0 2px;
}

/* 表格样式 */
.contract-content .item-table,
.item-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 12px;
    margin-bottom: 16px;
    font-size: 12px;
    border: 1px solid #000 !important;
}

.contract-content .item-table thead,
.item-table thead {
    background-color: #f5f5f5;
}

.contract-content .item-table th,
.item-table th {
    font-weight: 600;
    color: #171717;
    padding: 10px 8px;
    text-align: center;
    border: 1px solid #000 !important;
    background-color: #f5f5f5;
    vertical-align: middle;
}

.contract-content .item-table td,
.item-table td {
    padding: 8px;
    border: 1px solid #000 !important;
    text-align: center;
    vertical-align: middle;
    line-height: 1.6;
}

.contract-content .item-table tbody tr {
    background-color: #fff;
}

/* 表格中的左对齐文本（如备注列） */
.contract-content .item-table td[style*="text-align: left"] {
    text-align: left !important;
    padding-left: 10px;
}

/* 防止单价、总价列换行 */
.contract-content .item-table td:nth-child(5),
.contract-content .item-table td:nth-child(6),
.item-table td:nth-child(5),
.item-table td:nth-child(6) {
    white-space: nowrap;
}

/* 防止数量列换行（仅当没有white-space: normal样式时） */
.contract-content .item-table td:nth-child(3):not([style*="white-space: normal"]),
.item-table td:nth-child(3):not([style*="white-space: normal"]) {
    white-space: nowrap;
}

/* 通讯地址列允许换行 */
.item-table td[style*="white-space: normal"],
.contract-content .item-table td[style*="white-space: normal"] {
    white-space: normal !important;
    word-wrap: break-word;
    word-break: break-all;
}

/* 签名表格样式 */
.signature-table,
.print-format-wrapper .signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 24px;
    margin-bottom: 0;
    font-size: 12px;
    border: 1px solid #000;
}

.signature-table th,
.print-format-wrapper .signature-table th {
    font-weight: 600;
    color: #171717;
    padding: 12px;
    text-align: center;
    border: 1px solid #000;
    vertical-align: middle;
    width: 50%;
}

.signature-table td,
.print-format-wrapper .signature-table td {
    padding: 10px 20px;
    border: 1px solid #000;
    border-bottom-color: transparent;
    vertical-align: top;
    text-align: left;
    line-height: 1.45;
}

.signature-table tbody tr:last-child td,
.print-format-wrapper .signature-table tbody tr:last-child td {
    border-bottom-color: #000;
}

/* 签名信息样式 */
.signature-info {
    display: flex;
    align-items: flex-start;
    margin-bottom: 0;
}

.signature-label {
    font-weight: 600;
    color: #171717;
    display: inline-block;
    min-width: 80px;
    flex-shrink: 0;
    margin-bottom: 0;
}

.signature-value {
    color: #171717;
    flex: 1;
    word-wrap: break-word;
    word-break: break-all;
    margin-bottom: 0;
}

/* 响应式调整 */
@media print {
    /* 覆盖 standard.css 中 .print-format-wrapper { page-break-inside: avoid }，
       否则整份合同被当成不可拆块，首屏易被整块推到下一页出现大片空白。 */
    .print-format-wrapper.order-wrapper,
    .print-format-body {
        page-break-inside: auto !important;
    }

    .contract-content .section-title {
        page-break-after: avoid;
    }

    .contract-content .section-subtitle {
        page-break-after: auto;
    }

    .contract-content .item-table,
    .item-table {
        page-break-inside: auto !important;
    }

    .signature-table {
        page-break-inside: avoid;
    }
}

/* 确保表格在打印时正确显示 */
.contract-content .item-table,
.signature-table {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* 公司合同专用章：叠放在「企业税号」格内底部居中（甲方/乙方列） */
.signature-table td.signature-td-with-seal {
    position: relative;
    vertical-align: top;
    padding-bottom: 170px;
}

.company-seal-wrap {
    position: absolute;
    left: 50%;
    bottom: 10px;
    transform: translateX(-50%);
    width: 92%;
    max-width: 155px;
    text-align: center;
    line-height: 0;
}

.company-contract-seal {
    display: inline-block;
    max-width: 155px;
    max-height: 155px;
    width: auto;
    height: auto;
    object-fit: contain;
    /* 叠印：不透明度 + 正片叠底，减轻遮挡税号等文字（个别 PDF 引擎若混合异常可只保留 opacity） */
    opacity: 0.8;
    mix-blend-mode: multiply;
}

