/* 表格样式 */
.contract-content .item-table,
.item-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
    margin-bottom: 12px;
    font-size: 12px;
    border: 1px solid #000 !important;
}

.contract-content .item-table thead,
.item-table thead {
    background-color: #f5f5f5;
}

.contract-content .item-table th,
.item-table th {
    font-weight: 600;
    color: #171717;
    padding: 10px 8px;
    text-align: center;
    border: 1px solid #000 !important;
    background-color: #f5f5f5;
    vertical-align: middle;
}

.contract-content .item-table td,
.item-table td {
    padding: 8px;
    border: 1px solid #000 !important;
    text-align: center;
    vertical-align: middle;
    line-height: 1.6;
}

.contract-content .item-table tbody tr {
    background-color: #fff;
}

/* 表格中的左对齐文本（如备注列） */
.contract-content .item-table td[style*="text-align: left"] {
    text-align: left !important;
    padding-left: 10px;
}

/* 防止单价、总价列换行 */
.contract-content .item-table td:nth-child(5),
.contract-content .item-table td:nth-child(6),
.item-table td:nth-child(5),
.item-table td:nth-child(6) {
    white-space: nowrap;
}

/* 防止数量列换行（仅当没有white-space: normal样式时） */
.contract-content .item-table td:nth-child(3):not([style*="white-space: normal"]),
.item-table td:nth-child(3):not([style*="white-space: normal"]) {
    white-space: nowrap;
}

/* 通讯地址列允许换行 */
.item-table td[style*="white-space: normal"],
.contract-content .item-table td[style*="white-space: normal"] {
    white-space: normal !important;
    word-wrap: break-word;
    word-break: break-all;
}

/* 签名表格样式 */
.signature-table,
.print-format-wrapper .signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 16px;
    margin-bottom: 0;
    font-size: 12px;
    border: 1px solid #000;
}

.signature-table th,
.print-format-wrapper .signature-table th {
    font-weight: 600;
    color: #171717;
    padding: 12px;
    text-align: center;
    border: 1px solid #000;
    vertical-align: middle;
    width: 50%;
}

.signature-table td,
.print-format-wrapper .signature-table td {
    padding: 10px 20px;
    border: 1px solid #000;
    border-bottom-color: transparent;
    vertical-align: top;
    text-align: left;
    line-height: 1.45;
}

.signature-table tbody tr:last-child td,
.print-format-wrapper .signature-table tbody tr:last-child td {
    border-bottom-color: #000;
}

/* 签名信息样式 */
.signature-info {
    display: flex;
    align-items: flex-start;
    margin-bottom: 0;
}

.signature-label {
    font-weight: 600;
    color: #171717;
    display: inline-block;
    min-width: 80px;
    flex-shrink: 0;
    margin-bottom: 0;
}

.signature-value {
    color: #171717;
    flex: 1;
    word-wrap: break-word;
    word-break: break-all;
    margin-bottom: 0;
}

/* 响应式调整 */
@media print {
    /* 覆盖 standard.css 中 .print-format-wrapper { page-break-inside: avoid }，
       否则整份合同被当成不可拆块，首屏易被整块推到下一页出现大片空白。 */
    .print-format-wrapper.order-wrapper,
    .print-format-body {
        page-break-inside: auto !important;
    }

    .contract-content .section-title {
        page-break-after: avoid;
    }

    /* 小节标题后紧跟表格：避免与整表 avoid 叠加，导致表格单独起一页 */
    .contract-content .section-subtitle {
        page-break-after: auto;
    }

    .contract-content .item-table,
    .item-table {
        page-break-inside: auto !important;
    }

    .signature-table {
        page-break-inside: avoid;
    }
}

/* 确保表格在打印时正确显示 */
.item-table,
.signature-table {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* 公司合同专用章：叠放在「企业税号」格内底部居中（甲方/乙方列） */
.signature-table td.signature-td-with-seal {
    position: relative;
    vertical-align: top;
    padding-bottom: 170px;
}

.company-seal-wrap {
    position: absolute;
    left: 50%;
    bottom: 10px;
    transform: translateX(-50%);
    width: 92%;
    max-width: 155px;
    text-align: center;
    line-height: 0;
}

.company-contract-seal {
    display: inline-block;
    max-width: 155px;
    max-height: 155px;
    width: auto;
    height: auto;
    object-fit: contain;
    /* 叠印：不透明度 + 正片叠底，减轻遮挡税号等文字（个别 PDF 引擎若混合异常可只保留 opacity） */
    opacity: 0.8;
    mix-blend-mode: multiply;
}

/* ============================================
   打印格式样式 (Print Format Styles)
   适用于收付款申请（Payment Request）标准模板
   注意：通用样式已合并到 standard.css，此处仅保留模板特定样式
   ============================================ */

.print-format-wrapper .info-table {
	margin-bottom: 16px;
}

.print-format-wrapper .info-table .info-cell {
	padding: 4px;
	vertical-align: top;
}

.print-format-wrapper .info-label {
	display: inline-block;
	min-width: 72px;
	margin-right: 5px;
	color: #171717;
}

.print-format-wrapper .info-value {
	color: #171717;
}

.print-format-wrapper .items-table {
	margin-bottom: 16px;
}

.print-format-wrapper .item-info-cell {
	text-align: left;
}

.print-format-wrapper .secondary-text {
	font-size: 11px;
	color: #666;
	line-height: 1.3;
}

.print-format-wrapper .totals-table td {
	padding: 4px;
	vertical-align: middle;
}

.print-format-wrapper .signature-table td {
	padding: 4px;
	vertical-align: top;
}

/* 工业产品买卖合同（采购）— A4 单页紧凑版
 * 与 contract-and-terms-purchase 共用字段约定，仅版式与条款篇幅不同。
 */

@page {
    size: A4;
    margin: 6mm 7mm;
}

.contract-a4-wrap {
    font-family: "HarmonyOS Sans SC", "PingFangSC-Regular", "Microsoft YaHei", Arial, Helvetica, sans-serif;
    /* 单页紧凑仍须可读：略大于 10px，避免 PDF/引擎缩放后观感约 8px */
    font-size: 11.5px;
    line-height: 1.4;
    color: #171717;
    text-align: justify;
}

.contract-a4-wrap .contract-number {
    text-align: right;
    margin-bottom: 6px;
}

.contract-a4-wrap .contract-number .po-ref-inline {
    font-size: 0.92em;
    font-weight: normal;
    color: #333;
}

.contract-a4-wrap .header-title h2 {
    font-size: 18px;
    font-weight: 700;
    margin: 6px 0 4px;
    letter-spacing: 1px;
}

.contract-a4-wrap .meta-row {
    margin-bottom: 8px;
}

.contract-a4-wrap .party-label,
.contract-a4-wrap .meta-label {
    font-weight: 600;
}

.contract-a4-wrap .item-table {
    width: 100%;
    border-collapse: collapse;
    margin: 6px 0 7px;
    font-size: 10.75px;
    border: 1px solid #000 !important;
}

.contract-a4-wrap .item-table th,
.contract-a4-wrap .item-table td {
    padding: 3px 4px;
    border: 1px solid #000 !important;
    vertical-align: middle;
    line-height: 1.32;
}

.contract-a4-wrap .item-table th {
    font-weight: 600;
    text-align: center;
    background: #f5f5f5;
}

.contract-a4-wrap .taxes-summary-wrap {
    margin: 4px 0 8px;
    text-align: right;
}

.contract-a4-wrap .taxes-summary-table {
    margin-left: auto;
    width: 100%;
    max-width: 288px;
    border-collapse: collapse;
    font-size: 10.5px;
    border: 1px solid #000 !important;
    table-layout: fixed;
}

.contract-a4-wrap .taxes-summary-table td {
    padding: 3px 5px;
    border: 1px solid #000 !important;
    vertical-align: middle;
}

.contract-a4-wrap .taxes-summary-table td:first-child {
    width: 118px;
    white-space: nowrap;
}

.contract-a4-wrap .taxes-summary-table .taxes-grand-row td {
    background: #f0f0f0;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.contract-a4-wrap .taxes-summary-table .taxes-in-words-row td {
    vertical-align: top;
}

.contract-a4-wrap .taxes-summary-table .taxes-in-words-cell {
    line-height: 1.35;
    word-break: break-word;
}

.contract-a4-wrap .clauses {
    margin: 0;
    padding-left: 1.4em;
    font-size: 10.75px;
    line-height: 1.38;
}

.contract-a4-wrap .clauses li {
    margin-bottom: 5px;
}

.contract-a4-wrap .clauses li:last-child {
    margin-bottom: 0;
}

.contract-a4-wrap u {
    text-decoration: underline;
    text-underline-offset: 0.1em;
    padding: 0 1px;
}

/* 签名区：比通用合同更紧凑 */
.contract-a4-wrap .signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
    margin-bottom: 0;
    font-size: 10.75px;
    border: 1px solid #000;
}

.contract-a4-wrap .signature-table th {
    font-weight: 600;
    padding: 3px 6px;
    text-align: center;
    border: 1px solid #000;
    width: 50%;
}

.contract-a4-wrap .signature-table td {
    padding: 3px 6px 4px;
    border: 1px solid #000;
    vertical-align: top;
    text-align: left;
    line-height: 1.3;
}

.contract-a4-wrap .signature-info {
    display: flex;
    align-items: flex-start;
    margin-bottom: 1px;
}

.contract-a4-wrap .signature-label {
    font-weight: 600;
    min-width: 52px;
    flex-shrink: 0;
}

.contract-a4-wrap .signature-value {
    flex: 1;
    word-wrap: break-word;
    word-break: break-all;
}

.contract-a4-wrap .signature-table td.signature-td-with-seal {
    position: relative;
    padding-bottom: 72px;
}

.contract-a4-wrap .company-seal-wrap {
    position: absolute;
    left: 50%;
    bottom: 4px;
    transform: translateX(-50%);
    width: 88%;
    max-width: 100px;
    text-align: center;
    line-height: 0;
}

.contract-a4-wrap .company-contract-seal {
    display: inline-block;
    max-width: 100px;
    max-height: 100px;
    width: auto;
    height: auto;
    object-fit: contain;
    opacity: 0.82;
    mix-blend-mode: multiply;
}

@media print {
    .print-format-wrapper.order-wrapper,
    .print-format-body {
        page-break-inside: auto !important;
    }

    .contract-a4-wrap .signature-table {
        page-break-inside: avoid;
    }
}

.contract-a4-wrap .item-table,
.contract-a4-wrap .signature-table {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{%- set should_show_letterhead = True -%}
	{%- if print_settings and print_settings.with_letterhead == False -%}
		{%- set should_show_letterhead = False -%}
	{%- elif no_letterhead -%}
		{%- set should_show_letterhead = False -%}
	{%- endif -%}
	{%- if letter_head and should_show_letterhead -%}
		<div class="letter-head">{{ letter_head }}</div>
	{%- endif -%}
	{%- if print_heading_template -%}
		{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
	{%- endif -%}
{%- endmacro -%}

{%- macro signer_address_display(addr_link) -%}
{%- if addr_link -%}
{%- if frappe.db.exists('Address', addr_link) -%}
{{- frappe.db.get_value("Address", addr_link, "custom_address_display") or '' -}}
{%- else -%}
{{- addr_link -}}
{%- endif -%}
{%- endif -%}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break print-format-wrapper order-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>

	<div class="print-format-body contract-a4-wrap">
		{%- set seal_src = company_contract_seal_image_src(doc.company) if doc.company else '' -%}
		{%- set show_company_seal = seal_src and not doc.custom_hide_contract_seal -%}
		{# 打印上下文中 doc.meta.get_field 不可靠；以 doc.get 为准，未设置新字段时回退旧字段 #}
		{%- set _nr = doc.get('custom_is_print_item_remarks') -%}
		{%- if _nr is not none -%}
		{%- set show_item_desc = frappe.utils.cint(_nr) -%}
		{%- else -%}
		{%- set _old = doc.get('custom_print_item_description') -%}
		{%- set show_item_desc = frappe.utils.cint(_old if _old is not none else 1) -%}
		{%- endif -%}

		<div class="contract-number">
			<strong>合同编号：</strong>{{ doc.custom_contract_no or doc.name }}
			{%- if doc.custom_contract_no -%}
			<span class="po-ref-inline">（采购订单 {{ doc.name }}）</span>
			{%- endif -%}
		</div>

		<div class="header-title text-center">
			<h2 class="mb-0">工业产品买卖合同</h2>
		</div>

		<div class="row meta-row">
			<div class="col-xs-7">
				<div class="mb-1" style="white-space: nowrap;">
					<span class="party-label">甲方（需方）：</span><strong>{{ doc.custom_first_party_law or '' }}</strong>
				</div>
				<div class="mb-0" style="white-space: nowrap;">
					<span class="party-label">乙方（供方）：</span><strong>{{ doc.custom_second_party_law or '' }}</strong>
				</div>
			</div>
			<div class="col-xs-5 text-right">
				<div class="mb-1" style="white-space: nowrap;">
					<span class="meta-label">签订时间：</span>
					<strong>
						{%- set date = doc.get('custom_signing_date') or doc.transaction_date -%}
						{%- if date -%}
						{%- set date_str = frappe.utils.format_date(date, "yyyy-mm-dd") -%}
						{%- set date_parts = date_str.split("-") -%}
						{{ date_parts[0] }}年{{ date_parts[1] }}月{{ date_parts[2] }}日
						{%- endif -%}
					</strong>
				</div>
				<div class="mb-0" style="white-space: nowrap;">
					<span class="meta-label">签订地点：</span><strong>{{ doc.custom_signing_location or '' }}</strong>
				</div>
			</div>
		</div>

		<table class="item-table table table-bordered table-condensed">
			<thead>
				<tr>
					<th style="width:4%;">序</th>
					<th style="width:{% if show_item_desc %}22{% else %}30{% endif %}%;">名称</th>
					<th style="width:{% if show_item_desc %}16{% else %}22{% endif %}%;">规格型号</th>
					<th style="width:7%;">数量</th>
					<th style="width:6%;">单位</th>
					<th style="width:11%;">单价（元）</th>
					<th style="width:11%;">金额（元）</th>
					{% if show_item_desc %}<th style="width:23%;">备注</th>{% endif %}
				</tr>
			</thead>
			<tbody>
				{%- for item in doc.items -%}
				<tr>
					<td class="text-center">{{ loop.index }}</td>
					<td class="text-center">{{ item.item_name }}</td>
					<td class="text-left" style="white-space:normal;word-break:break-all;">{%- if item.item_code and not (item.get('custom_specification') or item.get('custom_model_number')) -%}
{%- set _spec_row = frappe.db.get_value('Item', item.item_code, ['custom_specification', 'custom_model_number'], as_dict=True) or {} -%}
{%- set _sp = (_spec_row.get('custom_specification') or '') | trim -%}
{%- set _mn = (_spec_row.get('custom_model_number') or '') | trim -%}
{%- else -%}
{%- set _sp = (item.get('custom_specification') or '') | trim -%}
{%- set _mn = (item.get('custom_model_number') or '') | trim -%}
{%- endif -%}
{%- if _sp and _mn -%}{{ _sp }} {{ _mn }}{%- elif _sp -%}{{ _sp }}{%- else -%}{{ _mn }}{%- endif -%}</td>
					<td class="text-center">{% if item.qty % 1 == 0 %}{{ "{:,.0f}".format(item.qty) }}{% else %}{{ "{:,.2f}".format(item.qty) }}{% endif %}</td>
					<td class="text-center">{{ item.uom }}</td>
					<td class="text-center" style="white-space:nowrap;">{{ "{:,.2f}".format(item.rate) }}</td>
					<td class="text-center" style="white-space:nowrap;">{{ "{:,.2f}".format(item.amount) }}</td>
					{% if show_item_desc %}<td class="text-left" style="white-space:normal;">{{ (item.description or "") | striptags }}</td>{% endif %}
				</tr>
				{%- endfor -%}
			</tbody>
		</table>

		{# 采购税费明细：与标准 PO 打印一致，便于合同与订单金额核对 #}
		<div class="taxes-summary-wrap">
			<table class="taxes-summary-table table table-bordered table-condensed">
				<tbody>
					<tr>
						<td class="text-right">货款小计（不含税）</td>
						<td class="text-right">{{ doc.get_formatted("total") }}</td>
					</tr>
					{%- for tax in (doc.taxes or []) -%}
					{%- if tax.tax_amount -%}
					<tr>
						<td class="text-right">{{ tax.description or tax.account_head or '' }}</td>
						<td class="text-right">{{ tax.get_formatted("tax_amount") }}</td>
					</tr>
					{%- endif -%}
					{%- endfor -%}
					<tr class="taxes-grand-row">
						<td class="text-right"><strong>价税合计（{{ doc.currency or "CNY" }}）</strong></td>
						<td class="text-right"><strong>{{ doc.get_formatted("grand_total") }}</strong></td>
					</tr>
					<tr class="taxes-in-words-row">
						<td class="text-right">大写金额</td>
						<td class="text-left taxes-in-words-cell"><u>{{ doc.in_words or '' }}</u></td>
					</tr>
				</tbody>
			</table>
		</div>

		<ol class="clauses">
			<li><strong>标的与质量：</strong>标的物为上表所列工业产品；质量符合国家标准、行业标准，有技术协议或图纸的从其约定；乙方保证产品为全新、未使用过的合格品。</li>
			<li><strong>交付与验收：</strong>交货期限、地点以双方确认的发货/收货信息为准；甲方应在到货后 <u>7</u> 日内验收，逾期未提出书面异议视为验收合格。</li>
			<li><strong>价款与支付：</strong>价款以上表为准；付款方式按订单「付款计划」执行，无计划时默认为合同签订后一次性支付；发票开具按双方约定或税务规定办理。</li>
			<li><strong>质保：</strong>质保期自验收合格之日起不少于 <u>{{ frappe.utils.cint(doc.get('custom_warranty_months')) or 12 }}</u> 个月（或双方另行书面约定）；质保期内因产品质量问题，乙方负责修理、更换或退货，费用由乙方承担。</li>
			<li><strong>违约与争议：</strong>任何一方违约给对方造成损失的，应承担赔偿责任；逾期付款或逾期交货的，违约方按逾期部分每日 <u>0.05</u> % 向对方支付违约金。争议协商不成的，提交<strong>有管辖权的人民法院</strong>诉讼解决。</li>
			<li><strong>生效：</strong>本合同自双方签字（盖章）之日起生效；一式两份，甲乙双方各执一份，具有同等法律效力。未尽事宜可签订补充协议，补充协议与本合同具有同等效力。</li>
		</ol>

		<table class="signature-table table table-bordered mb-0">
			<tbody>
				<tr>
					<th>甲方（需方）</th>
					<th>乙方（供方）</th>
				</tr>
				<tr>
					<td>
						<div class="signature-info"><span class="signature-label">单位名称：</span><span class="signature-value">{{ doc.custom_first_party_law or '' }}</span></div>
					</td>
					<td>
						<div class="signature-info"><span class="signature-label">单位名称：</span><span class="signature-value">{{ doc.custom_second_party_law or '' }}</span></div>
					</td>
				</tr>
				<tr>
					<td><div class="signature-info"><span class="signature-label">地址：</span><span class="signature-value">{{ signer_address_display(doc.custom_first_party_signer_address) or doc.billing_address_display or '' }}</span></div></td>
					<td><div class="signature-info"><span class="signature-label">地址：</span><span class="signature-value">{{ signer_address_display(doc.custom_second_party_signer_address) or doc.address_display or '' }}</span></div></td>
				</tr>
				<tr>
					<td><div class="signature-info"><span class="signature-label">代表：</span><span class="signature-value">{{ (doc.custom_first_party_signer or '').split('-')[0] }}</span></div></td>
					<td><div class="signature-info"><span class="signature-label">代表：</span><span class="signature-value">{{ (doc.custom_second_party_signer or '').split('-')[0] }}</span></div></td>
				</tr>
				<tr>
					<td><div class="signature-info"><span class="signature-label">电话：</span><span class="signature-value">{{ doc.custom_first_party_signer_phone or '' }}</span></div></td>
					<td><div class="signature-info"><span class="signature-label">电话：</span><span class="signature-value">{{ doc.custom_second_party_signer_phone or '' }}</span></div></td>
				</tr>
				<tr>
					<td><div class="signature-info"><span class="signature-label">开户行：</span><span class="signature-value">{{ doc.custom_payment_bank or '' }}</span></div></td>
					<td><div class="signature-info"><span class="signature-label">开户行：</span><span class="signature-value">{{ doc.custom_receipt_bank or '' }}</span></div></td>
				</tr>
				<tr>
					<td><div class="signature-info"><span class="signature-label">账号：</span><span class="signature-value">{{ doc.custom_payment_bank_account_no or '' }}</span></div></td>
					<td><div class="signature-info"><span class="signature-label">账号：</span><span class="signature-value">{{ doc.custom_receipt_bank_account_no or '' }}</span></div></td>
				</tr>
				<tr>
					<td {% if show_company_seal %}class="signature-td-with-seal"{% endif %}>
						<div class="signature-info"><span class="signature-label">税号：</span><span class="signature-value">{{ doc.custom_first_party_tax_id or '' }}</span></div>
						<div class="signature-info" style="margin-top:2px;"><span class="signature-label">（盖章）</span><span class="signature-value"></span></div>
						{% if show_company_seal %}
						<div class="company-seal-wrap" aria-hidden="true">
							<img src="{{ seal_src }}" class="company-contract-seal" alt="" />
						</div>
						{% endif %}
					</td>
					<td>
						<div class="signature-info"><span class="signature-label">税号：</span><span class="signature-value">{{ doc.custom_second_party_tax_id or '' }}</span></div>
						<div class="signature-info" style="margin-top:2px;"><span class="signature-label">（盖章）</span><span class="signature-value"></span></div>
					</td>
				</tr>
			</tbody>
		</table>
	</div>
</div>
{% endfor %}
